// sealedFamily is this rule's whole installed family: one row per plan row and
// the sealed state every invocation reads. Nothing here is mutated after the
// installer returns.
type sealedFamily struct {
	rows            []familyRow
	placementSchema placement.Schema
	valueSchema     *value.Schema
	plane           execution.FormPlane[placement.DenseCoordinate, placement.Fact]
	width           int
	read1Width      int
}

func (sealed *sealedFamily) NewExecutor(run *execution.Run) execution.Executor {
	if sealed == nil || run == nil {
		return nil
	}
	if sealed.read1Width < 0 {
		return nil
	}
	if sealed.width < 0 {
		return nil
	}
	// Every buffer is sized once at the sealed width of the selection this rule
	// spans, so an ordinary invocation allocates nothing.
	return &familyWorker{
		family:     sealed,
		run:        run,
		members:    make([]execution.RouteMember, sealed.width),
		cells:      make([]operand.SelectedCell[placement.Fact], sealed.width),
		routes:     make([]heap.Key, sealed.width),
		read1Cells: make([]operand.MemberCell[value.Value], sealed.read1Width),
	}
}

func (*sealedFamily) InputCapacity() int  { return 1 }
func (*sealedFamily) OutputCapacity() int { return 1 }

// familyWorker is one epoch's reusable invocation lane. Every scratch lives for
// the worker's lifetime, so a warm invocation opens its cursors and its write
// transaction without allocating.
type familyWorker struct {
	family     *sealedFamily
	run        *execution.Run
	read0      execution.Scratch[value.DenseCoordinate, value.Value]
	read1      execution.Scratch[value.DenseCoordinate, value.Value]
	read1Cells []operand.MemberCell[value.Value]
	read2      execution.SelectedScratch[placement.DenseCoordinate, placement.Fact]
	write      execution.RouteScratch[placement.DenseCoordinate, placement.Fact]
	members    []execution.RouteMember
	cells      []operand.SelectedCell[placement.Fact]
	routes     []heap.Key
}

// settle submits one non-publishing disposition. Every refusal path in this
// worker ends here, so the ticket is settled exactly once.
func (lane *familyWorker) settle(ticket execution.Ticket, outcome structure.ReductionOutcome) (execution.Result, bool) {
	if !ticket.Submit(outcome) {
		return execution.Result{}, false
	}
	return execution.NewResult(outcome, 0)
}

// Execute performs one routed invocation: the prerequisite reads are taken,
// the declared relation derives this candidate's route set once, the selection
// is observed at exactly those members, and one fold publishes at each.
func (lane *familyWorker) Execute(frame execution.Frame, ticket execution.Ticket) (execution.Result, bool) {
	if lane == nil || lane.family == nil || lane.run == nil || !frame.Valid(ticket) || !lane.run.Owns(ticket) {
		return execution.Result{}, false
	}
	local, localOK := ticket.LocalOrdinal()
	if !localOK || uint64(local) >= uint64(len(lane.family.rows)) {
		return execution.Result{}, false
	}
	row := lane.family.rows[local]
	var input0 value.Value
	switch lane.read0Cell(row.read0, row.read0Policy, ticket, &input0) {
	case structure.NoCandidate:
		return lane.settle(ticket, structure.NoCandidate)
	case structure.Refuse:
		return lane.settle(ticket, structure.Refuse)
	}
	read1Count := len(row.read1)
	if read1Count > len(lane.read1Cells) {
		return lane.settle(ticket, structure.Refuse)
	}
	read1Cells := lane.read1Cells[:read1Count]
	for index := 0; index < read1Count; index++ {
		if lane.read1Cell(row.read1[index], row.read1Policy, ticket, &read1Cells[index]) != structure.Concrete {
			return lane.settle(ticket, structure.Refuse)
		}
	}
	read1Vector, read1VectorOK := operand.NewMemberVector(read1Cells)
	if !read1VectorOK {
		return lane.settle(ticket, structure.Refuse)
	}
	// The route set is the relation's own answer, derived once per invocation from
	// the carriers its declaration names. Nothing below re-derives it.
	derived, derivedOK := deriveDerived2Rows(lane.family.placementSchema, lane.family.valueSchema, row.candidate, input0, read1Vector)
	if !derivedOK {
		return lane.settle(ticket, structure.Refuse)
	}
	count := derived2Count(derived)
	if count < 0 || count > len(lane.members) || count > len(lane.cells) || count > len(lane.routes) {
		return lane.settle(ticket, structure.Refuse)
	}
	members := lane.members[:count]
	cells := lane.cells[:count]
	routes := lane.routes[:count]
	for index := 0; index < count; index++ {
		selected, selectedOK := derived2At(derived, index)
		if !selectedOK {
			return lane.settle(ticket, structure.Refuse)
		}
		returnRouteKey, returnRouteKeyPaired, returnRouteKeyOK := selected.Coordinates()
		_ = returnRouteKeyPaired
		if !returnRouteKeyOK {
			return lane.settle(ticket, structure.Refuse)
		}
		returnRouteTag, returnRouteTagOK := selected.Predicate()
		if !returnRouteTagOK {
			return lane.settle(ticket, structure.Refuse)
		}
		returnRouteDestinationPaired, returnRouteDestination, returnRouteDestinationOK := selected.Coordinates()
		_ = returnRouteDestinationPaired
		if !returnRouteDestinationOK {
			return lane.settle(ticket, structure.Refuse)
		}
		dense, denseOK := lane.family.placementSchema.KeyIndex(returnRouteKey)
		if !denseOK {
			return lane.settle(ticket, structure.Refuse)
		}
		destinationDense, destinationDenseOK := lane.family.placementSchema.KeyIndex(returnRouteDestination)
		if !destinationDenseOK {
			return lane.settle(ticket, structure.Refuse)
		}
		member, memberOK := lane.family.plane.RouteMember(uint32(dense), uint32(destinationDense), uint64(returnRouteTag))
		if !memberOK {
			return lane.settle(ticket, structure.Refuse)
		}
		members[index] = member
		routes[index] = returnRouteDestination
	}
	// An empty derived relation is a read that named nothing, which is exhausted
	// rather than available; anything else is a selection that did not observe.
	status := row.read2.Observe(ticket, &lane.read2, members, cells)
	if count == 0 {
		if status != execution.ReadExhausted {
			return lane.settle(ticket, structure.Refuse)
		}
	} else if status != execution.ReadAvailable {
		return lane.settle(ticket, structure.Refuse)
	}
	outcome := execution.FoldSelectedRoute(ticket, row.write, &lane.write, cells, members, routes, familyReducer{})
	if !ticket.Submit(outcome) {
		return execution.Result{}, false
	}
	written := 0
	if outcome == structure.Concrete {
		written = 1
	}
	return execution.NewResult(outcome, written)
}

// read0Cell takes one exact prerequisite cell: the coordinate's whole delivery
// answered as the one cell it names, with the row's sealed policy settling
// what an unwritten coordinate delivers.
func (lane *familyWorker) read0Cell(read execution.ExactRead[value.DenseCoordinate, value.Value], policy execution.ReadCellPolicy[value.Value], ticket execution.Ticket, destination *value.Value) structure.ReductionOutcome {
	if lane == nil || destination == nil || !read.Valid() {
		return structure.Refuse
	}
	cell, status := execution.DeliverExactCell(read, policy, ticket, &lane.read0)
	switch status {
	case execution.ReadAvailable:
		if !cell.Present {
			return structure.NoCandidate
		}
		*destination = cell.Value
		return structure.Concrete
	case execution.ReadExhausted:
		return structure.NoCandidate
	default:
		return structure.Refuse
	}
}

// read1Cell takes one member of a nested set at its own sealed coordinate.
func (lane *familyWorker) read1Cell(read execution.ExactRead[value.DenseCoordinate, value.Value], policy execution.ReadCellPolicy[value.Value], ticket execution.Ticket, destination *operand.MemberCell[value.Value]) structure.ReductionOutcome {
	if lane == nil || destination == nil || !read.Valid() {
		return structure.Refuse
	}
	cell, status := execution.DeliverExactCell(read, policy, ticket, &lane.read1)
	if status != execution.ReadAvailable {
		return structure.Refuse
	}
	*destination = operand.MemberCell[value.Value]{Value: cell.Value, Present: cell.Present, Region: cell.Region}
	return structure.Concrete
}

// derived2InlineWidth is how many members join 2's set holds by value. It is the
// width its relation declares, which is that relation's own statement of how
// many members it ordinarily answers.
const derived2InlineWidth = 8

// derived2Member is one member and the address it is reached at: the coordinate
// its relation's declared key normalizes to, and the tag its declared
// predicate answers. Both are taken once, where the member is resolved,
// because asking the owner for them again per comparison would let two
// answers to one question disagree.
type derived2Member struct {
	dense uint32
	tag   uint64
	row   Route
}

// derived2Rows is the member set one invocation of join 2's declared relation
// answers. It is sealed by the Build below and read by nothing else.
//
// The ordinary answer is held BY VALUE in the bounded inline prefix and only a
// wider one reaches the explicit spill, so an invocation answering within the
// declared width allocates nothing at all.
type derived2Rows struct {
	inline [derived2InlineWidth]derived2Member
	spill  []derived2Member
	count  int

	// A widened answer is the owner's whole directory, which already lies in
	// the order this relation is ordered by, so nothing above holds it: the set
	// records that it widened, the census it took, and the inputs one member is
	// resolved from, and answers each member on demand.
	widened bool
	// widenPrefix states that every member the directory yields contributes one
	// row, so an ordinal IS a directory position and no scan is needed.
	widenPrefix          bool
	widenPlacementSchema placement.Schema
	widenValueSchema     *value.Schema
	widenCandidate       value.ReturnBoundary
}

func derived2Count(state derived2Rows) int { return state.count }

// derived2MemberAt answers one member of the set together with the coordinate it
// is ordered at. The inline prefix holds the first members and the spill holds
// the rest, in one order across both.
func derived2MemberAt(state derived2Rows, index int) (derived2Member, bool) {
	// A widened set placed nothing, so it holds no member here to answer with.
	if state.widened {
		return derived2Member{}, false
	}
	if index < 0 || index >= state.count {
		return derived2Member{}, false
	}
	if index < len(state.inline) {
		return state.inline[index], true
	}
	spilled := index - len(state.inline)
	if spilled >= len(state.spill) {
		return derived2Member{}, false
	}
	return state.spill[spilled], true
}

func derived2At(state derived2Rows, index int) (Route, bool) {
	if state.widened {
		return derived2WidenedAt(state, index)
	}
	member, memberOK := derived2MemberAt(state, index)
	if !memberOK {
		var absent Route
		return absent, false
	}
	return member.row, true
}

// insertDerived2Row places one resolved member at its canonical position.
//
// The set is ordered ascending by the coordinate its relation's declared key
// normalizes to, because that is the order the engine canonicalizes a
// selection by.
//
// A member is reached at that coordinate AND at the tag its predicate
// answers, and that pair is its whole address. Two items resolving to one
// address are one member named twice - an alias of the same thing - and the
// second adds no ordinal. Two items on one coordinate under DIFFERENT tags
// are two members where a selection carries one cell, which has no answer
// and is refused.
func insertDerived2Row(built derived2Rows, dense uint32, tag uint64, row Route) (derived2Rows, bool) {
	position := 0
	for position < built.count {
		current, currentOK := derived2MemberAt(built, position)
		if !currentOK {
			return derived2Rows{}, false
		}
		if current.dense == dense {
			if current.tag != tag {
				return derived2Rows{}, false
			}
			return built, true
		}
		if current.dense > dense {
			break
		}
		position++
	}
	placed := derived2Member{dense: dense, tag: tag, row: row}
	if built.count < len(built.inline) {
		for index := built.count; index > position; index-- {
			built.inline[index] = built.inline[index-1]
		}
		built.inline[position] = placed
		built.count++
		return built, true
	}
	// The prefix is full. A member belonging inside it displaces the last one
	// held there, and that one takes the first spilled position instead.
	if position < len(built.inline) {
		carried := built.inline[len(built.inline)-1]
		for index := len(built.inline) - 1; index > position; index-- {
			built.inline[index] = built.inline[index-1]
		}
		built.inline[position] = placed
		placed = carried
		position = len(built.inline)
	}
	spilled := position - len(built.inline)
	if spilled > len(built.spill) {
		return derived2Rows{}, false
	}
	built.spill = append(built.spill, derived2Member{})
	copy(built.spill[spilled+1:], built.spill[spilled:len(built.spill)-1])
	built.spill[spilled] = placed
	built.count++
	return built, true
}

// derived2WidenedAt answers one member of a widened set out of the directory it
// lies in. Nothing was copied when the set was built, so the member is
// resolved here, from the same inputs the census was taken over.
func derived2WidenedAt(state derived2Rows, index int) (Route, bool) {
	var absent Route
	if !state.widened || index < 0 || index >= state.count {
		return absent, false
	}
	widenCount := state.widenPlacementSchema.DenseKeyCount()
	if state.widenPrefix {
		if index >= widenCount {
			return absent, false
		}
		widenItem, widenItemOK := state.widenPlacementSchema.KeyAt(index)
		if !widenItemOK {
			return absent, false
		}
		widenRow, widenPresent, widenResolved := ResolveDirectoryRoute(state.widenPlacementSchema, state.widenValueSchema, state.widenCandidate, widenItem)
		if !widenResolved || !widenPresent {
			return absent, false
		}
		return widenRow, true
	}
	// The directory declines some of what it yields, so an ordinal is reached by
	// counting the members that contribute.
	ordinal := 0
	for widenCursor := 0; widenCursor < widenCount; widenCursor++ {
		widenItem, widenItemOK := state.widenPlacementSchema.KeyAt(widenCursor)
		if !widenItemOK {
			return absent, false
		}
		widenRow, widenPresent, widenResolved := ResolveDirectoryRoute(state.widenPlacementSchema, state.widenValueSchema, state.widenCandidate, widenItem)
		if !widenResolved {
			return absent, false
		}
		if !widenPresent {
			continue
		}
		if ordinal == index {
			return widenRow, true
		}
		ordinal++
	}
	return absent, false
}

// deriveDerived2Rows answers join 2's member set for one invocation.
// A source that reached its lattice endpoint named no alternatives at all, so
// the answer there is the owner's whole directory rather than the ones that
// happen to be written down. Both answers are placed the same way, so both
// leave in the one order a selection is canonicalized by.
func deriveDerived2Rows(placementSchema placement.Schema, valueSchema *value.Schema, given0 value.ReturnBoundary, given1 value.Value, given2 operand.SummaryVector[value.Value]) (derived2Rows, bool) {
	var built derived2Rows
	// The endpoint is the one judgment that runs whether or not the source
	// yields anything, so it is where an invocation nothing else would look at
	// is authenticated.
	beyond, admissible := BeyondAllocations(placementSchema, valueSchema, given0, given2)
	if !admissible {
		return derived2Rows{}, false
	}
	if beyond {
		built.widened = true
		built.widenPrefix = true
		built.widenPlacementSchema = placementSchema
		built.widenValueSchema = valueSchema
		built.widenCandidate = given0
		var widenPrevious uint32
		var widenSeen bool
		var widenGap bool
		widenCount := placementSchema.DenseKeyCount()
		for widenCursor := 0; widenCursor < widenCount; widenCursor++ {
			widenItem, widenItemOK := placementSchema.KeyAt(widenCursor)
			if !widenItemOK {
				return derived2Rows{}, false
			}
			widenRow, widenPresent, widenResolved := ResolveDirectoryRoute(placementSchema, valueSchema, given0, widenItem)
			if !widenResolved {
				return derived2Rows{}, false
			}
			if !widenPresent {
				widenGap = true
				continue
			}
			if widenGap {
				built.widenPrefix = false
			}
			returnRouteKey, returnRouteKeyPaired, returnRouteKeyOK := widenRow.Coordinates()
			_ = returnRouteKeyPaired
			if !returnRouteKeyOK {
				return derived2Rows{}, false
			}
			dense, denseOK := placementSchema.KeyIndex(returnRouteKey)
			if !denseOK {
				return derived2Rows{}, false
			}
			if widenSeen && dense <= widenPrevious {
				return derived2Rows{}, false
			}
			widenPrevious, widenSeen = dense, true
			built.count++
		}
		return built, true
	}
	count0 := given2.Count()
	for cursor0 := 0; cursor0 < count0; cursor0++ {
		cell0, cell0Present, cell0Available := given2.At(cursor0)
		item0, item0OK := valueSchema.AuthenticateFactorCell(cell0, cell0Present, cell0Available)
		if !item0OK {
			return derived2Rows{}, false
		}
		count1 := valueSchema.ValueAtomCount(item0)
		for cursor1 := 0; cursor1 < count1; cursor1++ {
			item1, item1OK := valueSchema.ValueAtomAt(item0, cursor1)
			if !item1OK {
				return derived2Rows{}, false
			}
			row, present, resolved := ResolveRoute(placementSchema, valueSchema, given0, item1)
			if !resolved {
				return derived2Rows{}, false
			}
			if present {
				returnRouteKey, returnRouteKeyPaired, returnRouteKeyOK := row.Coordinates()
				_ = returnRouteKeyPaired
				if !returnRouteKeyOK {
					return derived2Rows{}, false
				}
				returnRouteTag, returnRouteTagOK := row.Predicate()
				if !returnRouteTagOK {
					return derived2Rows{}, false
				}
				dense, denseOK := placementSchema.KeyIndex(returnRouteKey)
				if !denseOK {
					return derived2Rows{}, false
				}
				var placed bool
				built, placed = insertDerived2Row(built, dense, returnRouteTag, row)
				if !placed {
					return derived2Rows{}, false
				}
			}
		}
	}
	return built, true
}

// familyInstaller authors this rule's execution family. The axis schemas it
// holds are the ones the declaration names: the candidate directory it resolves
// dense candidates through, and every static axis a declared relation derives
// against. It reaches no owner callback and no runtime capability.
//
// It holds NO rule ordinal. Which rule an installer authors is the claim it
// was installed under, and the family table resolves an installer only for
// that claim; a copy kept here would be a second answer to a question the
// table already answers, and one that goes stale on its own.
type familyInstaller struct {
	placementSchema placement.Schema
	valueSchema     *value.Schema
}

// NewFamilyInstaller seals this rule's family installer against the axis schemas
// its declaration names. The bind arm that resolves those schemas from its
// composition's authorities is the owner's own, because how an authority
// record is reached is that composition's knowledge and not this rule's.
func NewFamilyInstaller(placementSchema placement.Schema, valueSchema *value.Schema) (execution.RuleFamilyInstaller[placement.DenseCoordinate, placement.Fact], bool) {
	install := familyInstaller{placementSchema: placementSchema, valueSchema: valueSchema}
	if !install.available() {
		return nil, false
	}
	return install, true
}

// available proves every schema this installer seals against was supplied.
// Whether a supplied schema is itself admissible is that schema's own answer,
// given below when a candidate or a projection is resolved through it.
func (install familyInstaller) available() bool {
	return install.valueSchema != nil
}

func (install familyInstaller) InstallRuleFamily(plane execution.FormPlane[placement.DenseCoordinate, placement.Fact], _ uint32, rows []execution.FormRow) (execution.Family, []execution.FormAddress, bool) {
	if !install.available() || !plane.Valid() || len(rows) == 0 {
		return nil, nil, false
	}
	sealed := &sealedFamily{rows: make([]familyRow, 0, len(rows)), placementSchema: install.placementSchema, valueSchema: install.valueSchema}
	width := plane.RouteWidth()
	if width < 0 {
		return nil, nil, false
	}
	sealed.plane, sealed.width = plane, width
	read1Width := 0
	addresses := make([]execution.FormAddress, 0, len(rows))
	for _, planRow := range rows {
		if planRow.Form != execution.FormSelectedRoute || !planRow.Rule.Available() || planRow.Rule.ReadCount() != 3 || planRow.Rule.OutputCount() != 1 {
			return nil, nil, false
		}
		output, outputOK := planRow.Rule.OutputAt(0)
		if !outputOK || output.Mode != program.ModeRoute || !output.RouteJoinPresent || output.RouteJoin != 2 || output.Slot != 0 {
			return nil, nil, false
		}
		carryMode, carryPresent := planRow.Rule.CarryMode()
		if carryPresent || carryMode != 0 {
			return nil, nil, false
		}
		plan0, plan0OK := planRow.Rule.ReadAt(0)
		if !plan0OK || plan0.Form != program.Exact || plan0.Input != 0 || plan0.PointBound != program.PointBound {
			return nil, nil, false
		}
		plan1, plan1OK := planRow.Rule.ReadAt(1)
		if !plan1OK || plan1.Form != program.Summary || plan1.Input != 0 || plan1.PointBound != program.PointBound {
			return nil, nil, false
		}
		plan2, plan2OK := planRow.Rule.ReadAt(2)
		if !plan2OK || plan2.Form != program.Selected || plan2.Input != 0 || plan2.PointBound != program.PointBound || plan2.Factor != output.Factor {
			return nil, nil, false
		}
		candidate, candidateOK := install.valueSchema.ReturnBoundaryAt(int(planRow.Candidate))
		if !candidateOK {
			return nil, nil, false
		}
		foreign0, foreign0OK := plane.Foreign(plan0.Factor)
		if !foreign0OK {
			return nil, nil, false
		}
		read0Sealed, read0SealedOK := execution.ForeignRowExactRead[value.DenseCoordinate, value.Value](foreign0, planRow, 0)
		read0Policy, read0PolicyOK := execution.ForeignReadCellPolicy[value.DenseCoordinate, value.Value](foreign0, plan0.Contract)
		if !read0PolicyOK {
			return nil, nil, false
		}
		foreign1, foreign1OK := plane.Foreign(plan1.Factor)
		if !foreign1OK {
			return nil, nil, false
		}
		read1Count, read1CountOK := planRow.MemberCount(1)
		if !read1CountOK {
			return nil, nil, false
		}
		read1Sealed := make([]execution.ExactRead[value.DenseCoordinate, value.Value], read1Count)
		for index := 0; index < read1Count; index++ {
			memberDense, memberDenseOK := planRow.MemberAt(1, index)
			if !memberDenseOK {
				return nil, nil, false
			}
			memberRead, memberReadOK := execution.ForeignMemberExactRead[value.DenseCoordinate, value.Value](foreign1, memberDense, uint16(plan1.Input))
			if !memberReadOK {
				return nil, nil, false
			}
			read1Sealed[index] = memberRead
		}
		if read1Count > read1Width {
			read1Width = read1Count
		}
		read1Policy, read1PolicyOK := execution.ForeignReadCellPolicy[value.DenseCoordinate, value.Value](foreign1, plan1.Contract)
		if !read1PolicyOK {
			return nil, nil, false
		}
		read2Sealed, read2SealedOK := plane.SelectedRead(uint16(plan2.Input), plan2.Contract, execution.ReadCellPolicy[placement.Fact]{})
		writeSealed, writeSealedOK := plane.RouteWrite(uint16(output.Slot))
		if !writeSealedOK || !read0SealedOK || !read2SealedOK {
			return nil, nil, false
		}
		addresses = append(addresses, execution.FormAddress{Member: planRow.Member, Local: uint32(len(sealed.rows))})
		sealed.rows = append(sealed.rows, familyRow{candidate: candidate, read0: read0Sealed, read0Policy: read0Policy, read1: read1Sealed, read1Policy: read1Policy, read2: read2Sealed, write: writeSealed})
	}
	sealed.read1Width = read1Width
	return sealed, addresses, true
}
